head.b:skin:
/* ============================================================
   SM TRADERS — BRAND DESIGN SYSTEM (ORANGE + CHARCOAL)
   Developer Credit: SynFusion
   ============================================================ */
:root {
  --orange-primary: #FF6A00;
  --orange-bright:  #FF8A00;
  --orange-deep:    #E65300;
  --orange-glow:    rgba(255, 106, 0, 0.20);
  --orange-soft:    rgba(255, 106, 0, 0.08);

  --charcoal:       #101010;
  --dark:           #171717;
  --soft-black:     #202020;

  --warm-white:     #FFFDFC;
  --bg-light:       #F7F5F2;

  --text-main:      #171717;
  --text-muted:     #666666;
  --border:         rgba(0, 0, 0, 0.08);
  --border-dark:    rgba(255, 255, 255, 0.10);

  --font-main:      'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --radius-sm:      8px;
  --radius-md:      14px;
  --radius-lg:      20px;
  --radius-xl:      28px;

  --shadow-sm:      0 2px 8px rgba(0,0,0,0.04);
  --shadow-md:      0 8px 24px rgba(0,0,0,0.08);
  --shadow-lg:      0 16px 40px rgba(0,0,0,0.12);
}

body {
  font-family: var(--font-main);
  background-color: var(--bg-light);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

button, input, select, textarea {
  font-family: inherit;
}

/* Kill Default Blogger Wrappers & CMS tags */
b\:skin, skin, #navbar-iframe, #b-navbar-iframe, .blogger-attribution, .post-feeds, .feed-links,
#Attribution1, .status-msg-wrap, .blog-pager, .quickedit, .widget-item-control,
#outer-wrapper, #content-wrapper, #main-wrapper, #sidebar-wrapper, .blog-posts, .widget, .main {
  display: none !important;
}

.sm-cms-hide {
  display: none !important;
}

/* Shared Container & Layout */
.container {
  width: 100%;
  max-width: 1240px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 16px;
  padding-right: 16px;
}

.sec-padding {
  padding-top: 80px;
  padding-bottom: 80px;
}

@media (max-width: 768px) {
  .sec-padding {
    padding-top: 56px;
    padding-bottom: 56px;
  }
}

.bg-dark {
  background-color: var(--charcoal);
  color: #ffffff;
}

.bg-warm {
  background-color: #ffffff;
}

.sec-header {
  text-align: center;
  max-width: 720px;
  margin: 0 auto 36px auto;
}

.eyebrow {
  display: inline-block;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--orange-primary);
  margin-bottom: 12px;
}

.sec-heading {
  font-size: 36px;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--charcoal);
  margin-bottom: 12px;
}

.bg-dark .sec-heading {
  color: #ffffff;
}

.sec-lead {
  font-size: 16px;
  color: var(--text-muted);
  line-height: 1.6;
}

.bg-dark .sec-lead {
  color: rgba(255, 255, 255, 0.7);
}

@media (max-width: 768px) {
  .sec-heading {
    font-size: 26px;
  }
  .sec-lead {
    font-size: 15px;
  }
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 48px;
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
  outline: none;
  white-space: nowrap;
  text-align: center;
}

.btn-primary {
  background: var(--orange-primary);
  color: #ffffff;
  box-shadow: 0 4px 14px var(--orange-glow);
}

.btn-primary:hover {
  background: var(--orange-bright);
  transform: translateY(-2px);
}

.btn-dark {
  background: var(--charcoal);
  color: #ffffff;
}

.btn-dark:hover {
  background: var(--soft-black);
}

.btn-ghost {
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.btn-ghost:hover {
  background: rgba(255, 255, 255, 0.2);
}

.btn-outline-dark {
  background: transparent;
  color: var(--charcoal);
  border: 1px solid var(--charcoal);
}

.btn-outline-dark:hover {
  background: var(--charcoal);
  color: #ffffff;
}

.btn-block {
  width: 100%;
}

/* ============================================================
   HEADER & NAVBAR
   ============================================================ */
.navbar-sticky {
  position: sticky;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(16, 16, 16, 0.94);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-dark);
}

.navbar-inner {
  display: flex;
  align-items: center;
  height: 72px;
  padding-inline: 16px;
  width: 100%;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-logo-mark {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--orange-primary), var(--orange-deep));
  color: #ffffff;
  font-weight: 900;
  font-size: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.brand-logo-text {
  display: flex;
  flex-direction: column;
}

.brand-title {
  font-size: 18px;
  font-weight: 800;
  color: #ffffff;
  letter-spacing: -0.01em;
  line-height: 1.1;
}

.brand-subtitle {
  font-size: 11px;
  font-weight: 700;
  color: var(--orange-primary);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.nav-spacer {
  flex: 1;
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: 24px;
}

.desktop-nav a {
  color: rgba(255, 255, 255, 0.8);
  font-size: 14px;
  font-weight: 600;
  transition: color 0.2s ease;
}

.desktop-nav a:hover {
  color: var(--orange-primary);
}

.header-cta {
  margin-left: 24px;
}

.hamburger-btn {
  display: none;
  width: 46px;
  height: 46px;
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-sm);
  color: #ffffff;
  cursor: pointer;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-left: auto;
}

.hamburger-btn span {
  display: block;
  width: 20px;
  height: 2px;
  background: #ffffff;
  border-radius: 2px;
  transition: all 0.2s ease;
}

@media (max-width: 991px) {
  .desktop-nav, .header-cta {
    display: none;
  }
  .hamburger-btn {
    display: flex;
  }
}

/* Mobile Drawer */
.mobile-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: 100%;
  max-width: 320px;
  height: 100vh;
  background: var(--charcoal);
  z-index: 2000;
  padding: 24px;
  display: flex;
  flex-direction: column;
  box-shadow: -10px 0 30px rgba(0,0,0,0.5);
  transition: right 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.mobile-drawer.active {
  right: 0;
}

.drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  z-index: 1999;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
}

.drawer-overlay.active {
  opacity: 1;
  visibility: visible;
}

.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border-dark);
}

.drawer-close {
  width: 44px;
  height: 44px;
  background: rgba(255,255,255,0.08);
  border: none;
  border-radius: 50%;
  color: #ffffff;
  font-size: 24px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.drawer-nav {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-top: 24px;
  padding-bottom: 24px;
}

.drawer-nav a {
  font-size: 16px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.9);
  padding: 8px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.drawer-nav a:hover {
  color: var(--orange-primary);
}

/* ============================================================
   HERO SECTION & SYNFUSION BRANDING
   ============================================================ */
.hero-sec {
  background: var(--charcoal);
  color: #ffffff;
  padding-top: 48px;
  padding-bottom: 64px;
  position: relative;
  overflow: hidden;
}

.synfusion-hero-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 100px;
  font-size: 12px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.9);
  margin-bottom: 24px;
}

.syn-dot {
  width: 7px;
  height: 7px;
  background-color: var(--orange-primary);
  border-radius: 50%;
  box-shadow: 0 0 8px var(--orange-primary);
  animation: synPulse 2.5s infinite ease-in-out;
}

@keyframes synPulse {
  0% { transform: scale(0.95); opacity: 0.6; box-shadow: 0 0 4px var(--orange-primary); }
  50% { transform: scale(1.15); opacity: 1; box-shadow: 0 0 12px var(--orange-primary); }
  100% { transform: scale(0.95); opacity: 0.6; box-shadow: 0 0 4px var(--orange-primary); }
}

@media (prefers-reduced-motion: reduce) {
  .syn-dot {
    animation: none;
  }
}

.hero-layout {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  width: 100%;
}

.hero-content {
  max-width: 800px;
  margin: 0 auto;
  width: 100%;
}

.hero-h1 {
  font-size: 48px;
  font-weight: 900;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: 16px;
  text-transform: uppercase;
}

.hero-h1 .highlight-text {
  color: var(--orange-primary);
  display: block;
}

.hero-sub {
  font-size: 18px;
  color: rgba(255, 255, 255, 0.8);
  max-width: 640px;
  margin: 0 auto 28px auto;
  line-height: 1.5;
}

.hero-ctas {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 48px;
}

@media (max-width: 768px) {
  .hero-h1 {
    font-size: 32px;
  }
  .hero-sub {
    font-size: 15px;
  }
  .hero-ctas {
    flex-direction: column;
    width: 100%;
  }
  .hero-ctas .btn {
    width: 100%;
  }
}

/* Wolf Mascot & Ground Shadow */
.wolf-stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  margin-top: 12px;
  width: 100%;
  max-width: 280px;
}

.wolf-img-wrap {
  width: 100%;
  max-width: 280px;
  position: relative;
  z-index: 2;
}

.wolf-img-wrap img {
  width: 100%;
  height: auto;
  object-fit: contain;
  display: block;
}

.wolf-soft-shadow {
  width: 220px;
  max-width: 80%;
  height: 18px;
  background: rgba(0, 0, 0, 0.65);
  border-radius: 50%;
  filter: blur(8px);
  margin-top: -10px;
  z-index: 1;
}

/* ============================================================
   HERO VIDEO SECTION ("SEE OUR WORK")
   ============================================================ */
.hero-video-sec {
  margin-top: 48px;
  width: 100%;
  max-width: 800px;
}

.video-sec-header {
  text-align: center;
  margin-bottom: 20px;
}

.video-sec-title {
  font-size: 22px;
  font-weight: 800;
  color: #ffffff;
}

.video-sec-sub {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.65);
  margin-top: 4px;
}

.custom-video-card {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: var(--dark);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border-dark);
  box-shadow: var(--shadow-lg);
  cursor: pointer;
}

.video-poster-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease, opacity 0.3s ease;
  display: block;
}

.custom-video-card:hover .video-poster-img {
  transform: scale(1.03);
}

.video-play-btn {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 64px;
  height: 64px;
  background: var(--orange-primary);
  color: #ffffff;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 8px 24px rgba(255, 106, 0, 0.4);
  transition: transform 0.2s ease, background 0.2s ease;
  z-index: 3;
  pointer-events: none;
}

.custom-video-card:hover .video-play-btn {
  transform: translate(-50%, -50%) scale(1.1);
  background: var(--orange-bright);
}

.video-iframe-wrap {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 4;
  display: none;
  background: #000;
}

.video-iframe-wrap iframe {
  width: 100%;
  height: 100%;
  border: none;
}

/* ============================================================
   ELECTRICAL PRODUCTS WHOLESALE (NEW MAJOR SECTION)
   ============================================================ */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 48px;
  width: 100%;
}

@media (max-width: 1024px) {
  .products-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 600px) {
  .products-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
}

.product-card {
  background: #ffffff;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  width: 100%;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: rgba(255, 106, 0, 0.3);
}

.product-img-aspect {
  width: 100%;
  aspect-ratio: 4 / 3;
  border-radius: var(--radius-sm);
  background: var(--bg-light);
  overflow: hidden;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.product-img-aspect img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.product-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--charcoal);
  margin-bottom: 4px;
}

.product-label {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 600;
}

/* Electrical Products Banner */
.products-banner {
  background: linear-gradient(135deg, var(--charcoal), var(--dark));
  border-radius: var(--radius-xl);
  padding: 40px;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  border: 1px solid var(--border-dark);
  width: 100%;
}

.banner-content {
  max-width: 600px;
}

.banner-title {
  font-size: 26px;
  font-weight: 800;
  margin-bottom: 8px;
  color: #ffffff;
}

.banner-text {
  font-size: 15px;
  color: rgba(255, 255, 255, 0.75);
  line-height: 1.5;
}

@media (max-width: 768px) {
  .products-banner {
    flex-direction: column;
    text-align: center;
    padding: 28px 20px;
  }
  .banner-title {
    font-size: 22px;
  }
}

/* ============================================================
   COMPLETE ELECTRICAL WORK
   ============================================================ */
.services-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin-bottom: 40px;
  width: 100%;
}

@media (max-width: 1100px) {
  .services-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 600px) {
  .services-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
}

.service-card {
  background: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  transition: transform 0.2s ease, border-color 0.2s ease;
  width: 100%;
}

.service-card:hover {
  transform: translateY(-3px);
  border-color: var(--orange-primary);
}

.service-icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: rgba(255, 106, 0, 0.1);
  color: var(--orange-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
}

.service-name {
  font-size: 14px;
  font-weight: 800;
  color: var(--charcoal);
  margin-bottom: 4px;
}

.service-desc {
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.3;
}

/* Transition Bar */
.transition-bar {
  text-align: center;
  background: var(--orange-soft);
  border: 1px solid rgba(255, 106, 0, 0.2);
  border-radius: var(--radius-md);
  padding: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  width: 100%;
}

.transition-text {
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
}

/* ============================================================
   SOLAR SECTION (PRESERVED UI + VIDEO CARDS)
   ============================================================ */
.solar-roadmap-sec {
  background: var(--charcoal);
  color: #ffffff;
  padding-top: 80px;
  padding-bottom: 80px;
}

.solar-cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
  width: 100%;
}

@media (max-width: 900px) {
  .solar-cards-grid {
    grid-template-columns: 1fr;
  }
}

.solar-card {
  background: var(--dark);
  border: 1px solid var(--border-dark);
  border-radius: var(--radius-lg);
  padding: 24px;
  display: flex;
  flex-direction: column;
  position: relative;
  width: 100%;
}

.solar-badge {
  align-self: flex-start;
  padding: 4px 10px;
  border-radius: 100px;
  background: rgba(255, 106, 0, 0.15);
  color: var(--orange-primary);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: 12px;
}

.solar-card-title {
  font-size: 20px;
  font-weight: 800;
  color: #ffffff;
  margin-bottom: 6px;
}

.solar-card-desc {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.7);
  margin-bottom: 16px;
  line-height: 1.4;
}

.solar-video-container {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: var(--radius-md);
  overflow: hidden;
  background: #000;
  margin-top: auto;
  cursor: pointer;
  border: 1px solid var(--border-dark);
}

/* Horizontal Solar Roadmap Diagram */
.solar-flow-path {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 48px;
  padding: 24px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border-dark);
  border-radius: var(--radius-lg);
  position: relative;
  width: 100%;
}

.flow-step {
  text-align: center;
  flex: 1;
}

.flow-step-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--orange-primary);
}

.flow-step-sub {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.6);
  margin-top: 4px;
}

.flow-arrow {
  color: var(--orange-primary);
  font-size: 20px;
  font-weight: 900;
}

@media (max-width: 768px) {
  .solar-flow-path {
    flex-direction: column;
    gap: 16px;
  }
  .flow-arrow {
    transform: rotate(90deg);
  }
}

/* ============================================================
   OUR WORK
   ============================================================ */
.portfolio-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  width: 100%;
}

@media (max-width: 900px) {
  .portfolio-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .portfolio-grid {
    grid-template-columns: 1fr;
  }
}

.portfolio-card {
  background: #ffffff;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  width: 100%;
}

.portfolio-img-wrap {
  width: 100%;
  aspect-ratio: 16 / 10;
  background: var(--charcoal);
  overflow: hidden;
}

.portfolio-img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.portfolio-info {
  padding: 20px;
}

.portfolio-tag {
  font-size: 11px;
  font-weight: 800;
  color: var(--orange-primary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.portfolio-title {
  font-size: 18px;
  font-weight: 800;
  color: var(--charcoal);
  margin: 4px 0 8px 0;
}

.portfolio-desc {
  font-size: 13px;
  color: var(--text-muted);
}

/* ============================================================
   ABOUT SM TRADERS & PROFILES
   ============================================================ */
.owners-row {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  max-width: 800px;
  margin: 0 auto;
  width: 100%;
}

@media (max-width: 600px) {
  .owners-row {
    gap: 16px;
  }
}

.owner-card {
  background: #ffffff;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  box-shadow: var(--shadow-sm);
  width: 100%;
}

.owner-avatar {
  width: 110px;
  height: 110px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--charcoal), var(--dark));
  border: 3px solid var(--orange-primary);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-size: 32px;
  font-weight: 900;
  overflow: hidden;
}

.owner-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.owner-name {
  font-size: 18px;
  font-weight: 800;
  color: var(--charcoal);
  margin-bottom: 4px;
}

.owner-role {
  font-size: 13px;
  font-weight: 700;
  color: var(--orange-primary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

@media (max-width: 600px) {
  .owner-avatar {
    width: 84px;
    height: 84px;
    font-size: 24px;
  }
  .owner-name {
    font-size: 16px;
  }
  .owner-role {
    font-size: 12px;
  }
}

/* ============================================================
   CONTACT & FORM
   ============================================================ */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  width: 100%;
}

@media (max-width: 850px) {
  .contact-grid {
    grid-template-columns: 1fr;
  }
}

.contact-info-list {
  display: flex;
  flex-direction: column;
  gap: 20px;
  width: 100%;
}

.contact-info-card {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-dark);
  border-radius: var(--radius-md);
  padding: 20px;
  width: 100%;
}

.contact-info-card b {
  display: block;
  color: var(--orange-primary);
  font-size: 12px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.contact-info-card p {
  color: #ffffff;
  font-size: 15px;
  font-weight: 600;
}

.contact-form {
  background: var(--dark);
  border: 1px solid var(--border-dark);
  border-radius: var(--radius-lg);
  padding: 32px;
  width: 100%;
}

.form-group {
  margin-bottom: 16px;
  width: 100%;
}

.form-group label {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 6px;
}

.form-group input, .form-group select, .form-group textarea {
  width: 100%;
  min-height: 48px;
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-dark);
  color: #ffffff;
  font-size: 14px;
  outline: none;
}

.form-group input:focus, .form-group select:focus, .form-group textarea:focus {
  border-color: var(--orange-primary);
}

/* ============================================================
   FLOATING WHATSAPP & ACTION MENU
   ============================================================ */
.floating-wa-btn {
  position: fixed;
  bottom: max(20px, env(safe-area-inset-bottom));
  right: 16px;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #25D366;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 8px 24px rgba(37, 211, 102, 0.4);
  z-index: 1500;
  cursor: pointer;
  border: none;
  transition: transform 0.2s ease;
  animation: waFloat 3s infinite ease-in-out;
}

@keyframes waFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

.floating-wa-btn:hover {
  transform: scale(1.08);
}

/* Action Menu Popup */
.action-menu-popup {
  position: fixed;
  bottom: max(84px, calc(env(safe-area-inset-bottom) + 64px));
  right: 16px;
  background: var(--charcoal);
  border: 1px solid var(--border-dark);
  border-radius: var(--radius-md);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: var(--shadow-lg);
  z-index: 1501;
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all 0.2s ease;
}

.action-menu-popup.active {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.action-menu-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  min-height: 44px;
  border-radius: var(--radius-sm);
  color: #ffffff;
  font-size: 13px;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.05);
  transition: background 0.2s ease;
}

.action-menu-item:hover {
  background: var(--orange-primary);
}

/* ============================================================
   CURVED FOOTER & SYNFUSION IDENTITY
   ============================================================ */
.footer-wrapper {
  background: var(--bg-light);
  padding-top: 40px;
  padding-bottom: 24px;
}

.footer-card {
  background: var(--charcoal);
  border-radius: var(--radius-xl) var(--radius-xl) 0 0;
  padding: 56px 24px 32px 24px;
  color: #ffffff;
  text-align: center;
}

.footer-brand-title {
  font-size: 24px;
  font-weight: 900;
  color: #ffffff;
  letter-spacing: -0.01em;
}

.footer-tagline {
  font-size: 13px;
  color: var(--orange-primary);
  font-weight: 700;
  margin-top: 4px;
  margin-bottom: 28px;
}

.footer-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  margin-bottom: 32px;
}

.footer-nav a {
  color: rgba(255, 255, 255, 0.7);
  font-size: 14px;
  font-weight: 600;
  transition: color 0.2s ease;
}

.footer-nav a:hover {
  color: #ffffff;
}

.footer-divider {
  height: 1px;
  background: var(--border-dark);
  max-width: 800px;
  margin: 0 auto 24px auto;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 800px;
  margin: 0 auto;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.5);
}

.synfusion-credit {
  font-weight: 800;
  color: var(--orange-primary);
  letter-spacing: 0.05em;
}

@media (max-width: 600px) {
  .footer-bottom {
    flex-direction: column;
    gap: 12px;
  }
}

body.script:
//
  (function () {
    "use strict";

    /* Inject skin stylesheet if loaded as raw XML in browser */
    try {
      var skinTag = document.querySelector("b\:skin, skin");
      if (skinTag && skinTag.textContent) {
        var styleEl = document.createElementNS("http://www.w3.org/1999/xhtml", "style");
        styleEl.setAttribute("type", "text/css");
        styleEl.textContent = skinTag.textContent;
        document.head.appendChild(styleEl);
      }
    } catch (e) {}

    /* Central Site Configuration Object */
    var SM_CONFIG = {
      businessName: "SM Traders",
      whatsapp: "919876543210",
      phone: "+919876543210",
      video: {
        heroWork: "cR4hOh_hzr8",
        solarOnGrid: "cR4hOh_hzr8",
        solarOffGrid: "cG3bkKJGzoc",
        solarHybrid: "SXS25kypZYg"
      },
      owners: [
        {
          name: "Mangesh Yendhe",
          role: "Shop Owner",
          initials: "MY"
        },
        {
          name: "Omkar Yendhe",
          role: "Electrician",
          initials: "OY"
        }
      ],
      products: [
        { name: "Wires & Cables", label: "House & Industrial", img: "https://images.unsplash.com/photo-1544724569-5f546fd6f2b5?auto=format&fit=crop&w=400&q=80" },
        { name: "Switches & Sockets", label: "Modular & Standard", img: "https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=400&q=80" },
        { name: "MCB & DB", label: "Protection Boards", img: "https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&w=400&q=80" },
        { name: "LED Lights", label: "Panels, Bulbs & Strips", img: "https://images.unsplash.com/photo-1565814636199-ae8133055c1c?auto=format&fit=crop&w=400&q=80" },
        { name: "Fans", label: "Ceiling & Exhaust", img: "https://images.unsplash.com/photo-1618956880010-f1c50075e718?auto=format&fit=crop&w=400&q=80" },
        { name: "Electrical Accessories", label: "Plugs, Tapes & Junctions", img: "https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=400&q=80" },
        { name: "Conduits & Fittings", label: "PVC & Metal Pipes", img: "https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=400&q=80" },
        { name: "Switchgear", label: "Heavy Duty Gear", img: "https://images.unsplash.com/photo-1581092335397-9583fe92d232?auto=format&fit=crop&w=400&q=80" },
        { name: "Electrical Tools", label: "Professional Testers", img: "https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=400&q=80" },
        { name: "Other Electrical Items", label: "Full Range Available", img: "https://images.unsplash.com/photo-1517420704952-d9f39e95b43e?auto=format&fit=crop&w=400&q=80" }
      ],
      services: [
        { name: "House Wiring", desc: "New wiring &amp; setup" },
        { name: "Shop &amp; Office Wiring", desc: "Complete wiring" },
        { name: "Electrical Repair", desc: "Fault finding &amp; repair" },
        { name: "Switch &amp; Socket Installation", desc: "Installation &amp; replacement" },
        { name: "Fan &amp; Light Installation", desc: "Fitting &amp; installation" },
        { name: "MCB &amp; DB Work", desc: "Protection &amp; distribution" },
        { name: "Meter &amp; Connection Work", desc: "Electrical connection work" },
        { name: "Inverter Setup", desc: "Backup power setup" },
        { name: "New Electrical Installation", desc: "Complete electrical setup" },
        { name: "Maintenance &amp; Repair", desc: "Electrical maintenance" }
      ],
      solarTypes: [
        {
          type: "ON-GRID",
          title: "On-Grid Solar System",
          desc: "Works with the electricity grid. Best for homes and businesses with regular grid power.",
          videoId: "cR4hOh_hzr8"
        },
        {
          type: "OFF-GRID",
          title: "Off-Grid Solar System",
          desc: "Works with solar and battery power. Useful where grid power is not available or reliable.",
          videoId: "cG3bkKJGzoc"
        },
        {
          type: "HYBRID",
          title: "Hybrid Solar System",
          desc: "Solar + grid + battery. Good for homes and businesses that need backup power.",
          videoId: "SXS25kypZYg"
        }
      ],
      projects: [
        { title: "Residential House Wiring", tag: "Electrical Work", desc: "Complete concealed copper wiring for multi-story residence." },
        { title: "Rooftop Solar Setup", tag: "Solar Solutions", desc: "5kW On-Grid solar installation for monthly bill savings." },
        { title: "Shop Electrical Setup", tag: "Electrical Work", desc: "Commercial LED lights, DB box and modular switch layout." }
      ]
    };

    var $ = function (s, c) { return (c || document).querySelector(s); };
    var $$ = function (s, c) { return Array.prototype.slice.call((c || document).querySelectorAll(s)); };

    function escapeXml(str) {
      return String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    /* Mobile Drawer */
    var hamburgerBtn = $("#hamburgerBtn");
    var drawerClose = $("#drawerClose");
    var mobileDrawer = $("#mobileDrawer");
    var drawerOverlay = $("#drawerOverlay");

    function openDrawer() {
      if (mobileDrawer) mobileDrawer.classList.add("active");
      if (drawerOverlay) drawerOverlay.classList.add("active");
      document.body.style.overflow = "hidden";
    }

    function closeDrawer() {
      if (mobileDrawer) mobileDrawer.classList.remove("active");
      if (drawerOverlay) drawerOverlay.classList.remove("active");
      document.body.style.overflow = "";
    }

    if (hamburgerBtn) hamburgerBtn.addEventListener("click", openDrawer);
    if (drawerClose) drawerClose.addEventListener("click", closeDrawer);
    if (drawerOverlay) drawerOverlay.addEventListener("click", closeDrawer);

    $$("#mobileDrawer a").forEach(function (link) {
      link.addEventListener("click", closeDrawer);
    });

    /* Render Product Cards */
    function renderProducts() {
      var grid = $("#productsGrid");
      if (!grid) return;

      grid.innerHTML = SM_CONFIG.products.map(function (p) {
        return '<div class="product-card">' +
          '<div class="product-img-aspect">' +
            '<img src="' + escapeXml(p.img) + '" alt="' + escapeXml(p.name) + '" loading="lazy" />' +
          '</div>' +
          '<h3 class="product-title">' + escapeXml(p.name) + '</h3>' +
          '<span class="product-label">' + escapeXml(p.label) + '</span>' +
        '</div>';
      }).join('');
    }

    /* Render Services */
    function renderServices() {
      var grid = $("#servicesGrid");
      if (!grid) return;

      var boltSvg = '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M13 2 4 14h6l-1 8 9-12h-6l1-8Z"/></svg>';

      grid.innerHTML = SM_CONFIG.services.map(function (s) {
        return '<div class="service-card">' +
          '<div class="service-icon">' + boltSvg + '</div>' +
          '<h3 class="service-name">' + s.name + '</h3>' +
          '<p class="service-desc">' + s.desc + '</p>' +
        '</div>';
      }).join('');
    }

    /* Video Player Helper */
    function initCustomVideoPlayer(cardEl, videoId) {
      if (!cardEl) return;

      var iframeWrap = cardEl.querySelector(".video-iframe-wrap") || cardEl.querySelector("#heroVideoIframeWrap");

      function loadIframe() {
        if (!iframeWrap || iframeWrap.dataset.loaded === "true") return;
        iframeWrap.dataset.loaded = "true";
        iframeWrap.style.display = "block";
        iframeWrap.innerHTML = '<iframe src="https://www.youtube-nocookie.com/embed/' + encodeURIComponent(videoId) + '?autoplay=1&amp;rel=0" title="YouTube video player" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen="allowfullscreen"></iframe>';
      }

      cardEl.addEventListener("click", function () {
        loadIframe();
      });

      /* Desktop Muted Hover Preview */
      if (window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
        var hoverTimeout;
        cardEl.addEventListener("mouseenter", function () {
          if (iframeWrap && iframeWrap.dataset.loaded === "true") return;
          hoverTimeout = setTimeout(function () {
            if (iframeWrap && !iframeWrap.dataset.loaded) {
              iframeWrap.style.display = "block";
              iframeWrap.innerHTML = '<iframe src="https://www.youtube-nocookie.com/embed/' + encodeURIComponent(videoId) + '?autoplay=1&amp;mute=1&amp;controls=0&amp;loop=1&amp;playlist=' + encodeURIComponent(videoId) + '&amp;rel=0" title="YouTube Video Preview" allow="autoplay" style="pointer-events:none;"></iframe>';
            }
          }, 400);
        });

        cardEl.addEventListener("mouseleave", function () {
          clearTimeout(hoverTimeout);
          if (iframeWrap && iframeWrap.dataset.loaded !== "true") {
            iframeWrap.style.display = "none";
            iframeWrap.innerHTML = "";
          }
        });
      }
    }

    /* Render Solar Cards */
    function renderSolarCards() {
      var grid = $("#solarCardsGrid");
      if (!grid) return;

      grid.innerHTML = SM_CONFIG.solarTypes.map(function (s, idx) {
        return '<div class="solar-card">' +
          '<span class="solar-badge">' + escapeXml(s.type) + '</span>' +
          '<h3 class="solar-card-title">' + escapeXml(s.title) + '</h3>' +
          '<p class="solar-card-desc">' + escapeXml(s.desc) + '</p>' +
          '<div class="solar-video-container" id="solarVideoCard_' + idx + '" data-video-id="' + escapeXml(s.videoId) + '">' +
            '<img class="video-poster-img" src="https://img.youtube.com/vi/' + escapeXml(s.videoId) + '/hqdefault.jpg" alt="' + escapeXml(s.title) + ' Video Preview" loading="lazy"/>' +
            '<div class="video-play-btn"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg></div>' +
            '<div class="video-iframe-wrap"></div>' +
          '</div>' +
        '</div>';
      }).join('');

      SM_CONFIG.solarTypes.forEach(function (s, idx) {
        var el = $("#solarVideoCard_" + idx);
        if (el) initCustomVideoPlayer(el, s.videoId);
      });
    }

    /* Render Our Work */
    function renderPortfolio() {
      var grid = $("#portfolioGrid");
      if (!grid) return;

      var svgPlaceholder = '<div style="width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;background:var(--charcoal);color:#fff;padding:16px;text-align:center;"><svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="var(--orange-primary)" stroke-width="1.5"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m21 15-5-5L5 21"/></svg><span style="margin-top:8px;font-size:12px;color:var(--orange-primary);font-weight:700;">SM TRADERS WORK</span></div>';

      grid.innerHTML = SM_CONFIG.projects.map(function (p) {
        return '<div class="portfolio-card">' +
          '<div class="portfolio-img-wrap">' + svgPlaceholder + '</div>' +
          '<div class="portfolio-info">' +
            '<span class="portfolio-tag">' + escapeXml(p.tag) + '</span>' +
            '<h3 class="portfolio-title">' + escapeXml(p.title) + '</h3>' +
            '<p class="portfolio-desc">' + escapeXml(p.desc) + '</p>' +
          '</div>' +
        '</div>';
      }).join('');
    }

    /* Render Owners */
    function renderOwners() {
      var grid = $("#ownersGrid");
      if (!grid) return;

      grid.innerHTML = SM_CONFIG.owners.map(function (o) {
        return '<div class="owner-card">' +
          '<div class="owner-avatar">' + escapeXml(o.initials) + '</div>' +
          '<h3 class="owner-name">' + escapeXml(o.name) + '</h3>' +
          '<span class="owner-role">' + escapeXml(o.role) + '</span>' +
        '</div>';
      }).join('');
    }

    /* Floating WhatsApp Popup */
    var floatingWaBtn = $("#floatingWaBtn");
    var actionMenuPopup = $("#actionMenuPopup");
    var waMenuItem = $("#waMenuItem");

    function buildWaUrl(msg) {
      var num = SM_CONFIG.whatsapp.replace(/[^0-9]/g, "");
      var text = encodeURIComponent(msg || "Hello SM Traders, I would like to enquire about your services.");
      return "https://wa.me/" + num + "?text=" + text;
    }

    if (waMenuItem) waMenuItem.href = buildWaUrl();

    if (floatingWaBtn && actionMenuPopup) {
      floatingWaBtn.addEventListener("click", function (e) {
        e.stopPropagation();
        actionMenuPopup.classList.toggle("active");
      });

      document.addEventListener("click", function (e) {
        if (!actionMenuPopup.contains(e.target) && e.target !== floatingWaBtn) {
          actionMenuPopup.classList.remove("active");
        }
      });
    }

    /* Contact Form Submission via WhatsApp */
    var contactForm = $("#contactForm");
    if (contactForm) {
      contactForm.addEventListener("submit", function (e) {
        e.preventDefault();
        var name = $("#reqName") ? $("#reqName").value : "";
        var phone = $("#reqPhone") ? $("#reqPhone").value : "";
        var service = $("#reqService") ? $("#reqService").value : "";
        var msg = $("#reqMsg") ? $("#reqMsg").value : "";

        var text = "New Enquiry for SM Traders:\n" +
          "Name: " + name + "\n" +
          "Phone: " + phone + "\n" +
          "Service: " + service + "\n" +
          "Details: " + msg;

        window.open(buildWaUrl(text), "_blank");
      });
    }

    /* Initialize Everything */
    document.addEventListener("DOMContentLoaded", function () {
      renderProducts();
      renderServices();
      renderSolarCards();
      renderPortfolio();
      renderOwners();

      var heroVideoCard = $("#heroVideoCard");
      if (heroVideoCard) initCustomVideoPlayer(heroVideoCard, SM_CONFIG.video.heroWork);
    });

  })();
  //
